package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import org.apache.commons.jxpath.Expression;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.InfoSetUtil;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.axes.SelfContext;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CoreOperationCompare_findMatch_TriageGen0Test {

    private CoreOperationCompare sut;
    private Expression mockExpr1;
    private Expression mockExpr2;

    @Before
    public void setUp() {
        mockExpr1 = mock(Expression.class);
        mockExpr2 = mock(Expression.class);
        // Since findMatch is protected, we use a subclass or spy to access it
        sut = spy(new CoreOperationCompare(mockExpr1, mockExpr2));
    }

    @Test
    public void testFindMatch_BothIteratorsEmpty_ReturnsFalse() {
        Iterator<Object> lit = Collections.emptyIterator();
        Iterator<Object> rit = Collections.emptyIterator();

        boolean result = sut.findMatch(lit, rit);

        assertFalse(result);
    }

    @Test
    public void testFindMatch_LeftEmptyRightNotEmpty_ReturnsFalse() {
        Iterator<Object> lit = Collections.emptyIterator();
        Iterator<Object> rit = Arrays.asList("A", "B").iterator();

        // contains() will be called, but left HashSet is empty
        doReturn(false).when(sut).contains(any(), any());

        boolean result = sut.findMatch(lit, rit);

        assertFalse(result);
        verify(sut, atLeastOnce()).contains(any(), any());
    }

    @Test
    public void testFindMatch_LeftNotEmptyRightEmpty_ReturnsFalse() {
        Iterator<Object> lit = Arrays.asList("A", "B").iterator();
        Iterator<Object> rit = Collections.emptyIterator();

        boolean result = sut.findMatch(lit, rit);

        assertFalse(result);
    }

    @Test
    public void testFindMatch_MatchFound_ReturnsTrue() {
        Iterator<Object> lit = Arrays.asList("A", "B").iterator();
        Iterator<Object> rit = Arrays.asList("B", "C").iterator();

        // Simulate finding "B" in the left set
        doReturn(true).when(sut).contains(any(), eq("B"));

        boolean result = sut.findMatch(lit, rit);

        assertTrue(result);
    }

    @Test
    public void testFindMatch_NoMatchFound_ReturnsFalse() {
        Iterator<Object> lit = Arrays.asList("A", "B").iterator();
        Iterator<Object> rit = Arrays.asList("C", "D").iterator();

        // Simulate no matches found
        doReturn(false).when(sut).contains(any(), any());

        boolean result = sut.findMatch(lit, rit);

        assertFalse(result);
    }

    @Test
    public void testFindMatch_SingleElementMatch_ReturnsTrue() {
        Iterator<Object> lit = Collections.singletonList("X").iterator();
        Iterator<Object> rit = Collections.singletonList("X").iterator();

        doReturn(true).when(sut).contains(any(), eq("X"));

        boolean result = sut.findMatch(lit, rit);

        assertTrue(result);
    }
}
